            except ValidationError:
                return Response({"detail": {"code": MISSING_PASSWORD_OR_U2F_CODE}}, status=400)

        if not authenticated:
            return Response({"detail": {"code": "ignore"}}, status=status.HTTP_403_FORBIDDEN)

        try:
