            ),
            ("Abandoned Leases", "%s" % Lease.objects.filter(abandoned=True).count()),
            (
                "Networks: (Total / Wireless)",
                "%s / %s" % (Network.objects.all().count(), wireless_networks.count()),
            ),
            (
                "Available Wireless Addresses",
