            _profile_image_url=picture,
            group_ids=[org.default_group.id],
        )
        models.db.session.add(user_object)
        models.db.session.commit()

    login_user(user_object, remember=True)

    return user_object


def get_next_path(unREDACTED5_next_path):
    if not unREDACTED5_next_path:
        return ""

    # Preventing open redirection attacks
    parts = list(urlsplit(unREDACTED5_next_path))
    parts[0] = ""  # clear scheme
    parts[1] = ""  # clear netloc
    REDACTED5_next_path = urlunsplit(parts)

    # If the original path was a URL, we might end up with an empty
    # REDACTED5 url, which will redirect to the login page. Changing to
    # relative root to redirect to the app root after login.
    if not REDACTED5_next_path:
        REDACTED5_next_path = "./"

    return REDACTED5_next_path

