        )
        if not serializer.is_valid():
            return FormattedResponse(
                m="invalid_token_or_uid",
                d=serializer.errors,
                status=HTTP_400_BAD_REQUEST,
            )
        user = serializer.validated_data["user"]
        if user.email_verified:
