        self.url = kwargs.get('url', '')
        self.sleep = kwargs.get('sleep', None)
        super().__init__()

    def __str__(self):
        return str(self.return_type)


class DAWebError(Exception):

    def __init__(self, **kwargs):
        for key, val in kwargs.items():
            setattr(self, key, val)
        super().__init__()

