def makemodechange(bot, trigger, mode, isusermode=False, isbqmode=False, selfREDACTED5=False):
    """Change the channel mode."""
    chanops = get_chanops(str(trigger.sender), bot.memory['channelmgnt']['jdcache'])
    dodeop = False
