                    annot_kid = None
                    while not (hasattr(annot, "FT") and hasattr(annot, "T")) and hasattr(annot, 'Parent'):
                        annot_kid = annot
                        annot = annot.Parent
                    if not (hasattr(annot, "T") and hasattr(annot, "FT")):
                        continue
                    if field != str(annot.T):
                        continue
                    field_type = str(annot.FT)
                    if field_type == "/Tx":
                        the_string = pikepdf.String(value)
                        annot.V = the_string
                        annot.DV = the_string
                    elif field_type == "/Btn":
                        if hasattr(annot, "A"):
                            continue
