    for a[1] in range(10):
        pass
    """,
        StructureException,
        "Invalid syntax for loop iterator",
        "a[1]",
    ),
    (
        """
@external
def foo():
    x: uint256 = 100
    for _ in range(10, bound=x):
        pass
    """,
        StateAccessViolation,
        "Bound must be a literal",
        "x",
    ),
    (
        """
@external
def foo():
    for _ in range(10, 20, bound=5):
        pass
    """,
        StructureException,
        "Please remove the `bound=` kwarg when using range with constants",
        "5",
    ),
    (
        """
@external
